#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int  gr,fr;  enum EDirect eDir;  RGBTRIPLE rgb[3];//0-фон,1-свет,2-тьма  } Queue_DnoT;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(RGBTRIPLE& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void GradientTriangle( HDC hDC, RECT rc, int grad, int frame, EDirect eDir, RGBTRIPLE* rgb )  {  POINT pt[3];  switch ( eDir )    {    case dirDown:      pt[0].x = rc.left ;pt[0].y = rc.top;      pt[1].x = (rc.left+rc.right)/2;pt[1].y = rc.bottom;      pt[2].x = rc.right;pt[2].y = rc.top;    break;    case dirUp  :      pt[0].x = rc.left ;pt[0].y = rc.bottom;      pt[1].x = (rc.left+rc.right)/2;pt[1].y = rc.top;      pt[2].x = rc.right;pt[2].y = rc.bottom;    break;    case dirLeft :      pt[0].x = rc.right;pt[0].y = rc.top;      pt[1].x = rc.left ;pt[1].y = (rc.bottom+rc.top)/2;      pt[2].x = rc.right;pt[2].y = rc.bottom;    break;    case dirRight:      pt[0].x = rc.left ;pt[0].y = rc.top;      pt[1].x = rc.right;pt[1].y = (rc.bottom+rc.top)/2;      pt[2].x = rc.left ;pt[2].y = rc.bottom;    break;    default:      return;    }  //  bool bVert = eDir == dirUp || eDir == dirDown;  //  // Заливка области  if ( grad > 1 )  {  CMyRgn rgn( hDC, Rgb(rgb[0]), frame );  ::Polygon( hDC, pt, 3 );  }  //  int part;  if ( bVert )    {    part = ( rc.right-rc.left )/grad;    pt[0].x+=part,pt[2].x-=part;    }  else    {    part = ( rc.bottom-rc.top )/grad;    pt[0].y+=part,pt[2].y-=part;    }  //  int pirt = part;  if ( frame == 0 ) pirt--;  //  for ( int n = 1; n <= pirt; n++ )    {    //    if ( bVert ) { pt[0].x--,pt[2].x++; }    else         { pt[0].y--,pt[2].y++; }    //    {// Используем свойства локального стека для деструктора CMyPen    CMyPen pen( hDC, (n==part)?0:Col(rgb[0],rgb[1],n,part) );    ::MoveToEx( hDC, pt[1].x, pt[1].y, NULL );    ::LineTo  ( hDC, pt[0].x, pt[0].y );    }    {// Используем свойства локального стека для деструктора CMyPen    CMyPen pen( hDC, (n==part)?0:Col(rgb[0],rgb[2],n,part) );    ::MoveToEx( hDC, pt[1].x, pt[1].y, NULL );    ::LineTo  ( hDC, pt[2].x, pt[2].y );    }    }//for ( int n = 1; n < part; n++ )  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintDnoT(DefinePaint)  {  QueueP(Queue_DnoT);  GradientTriangle( hDC, p->mRect, p->gr, p->fr, p->eDir, p->rgb );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddDnoT(DefineTegs)  {  AddQueueEx(Queue_DnoT);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintDnoT;  //  COLORREF fon   = 0xfffffe;//0-фон  COLORREF light = 0x888888;//1-свет  COLORREF dark  = 0x888888;//2-тьма  p->gr = 1;  //  STegObj obj[] =    {    { 'R', "rect"  , &p->mRect },    { 'E', "rc"    , &p->mRect },    { 'A', "fon"   , &fon   },    { 'A', "light" , &light },    { 'A', "dark"  , &dark  },    { 'A', "f"     , &fon   },    { 'A', "l"     , &light },    { 'A', "d"     , &dark  },    { 'I', "frame" , &p->fr },    { 'I', "g"     , &p->gr },    { 'I', "grad"  , &p->gr },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->eDir = ParserDirect(teg[0].value);  SetT(p->rgb[0],fon  );  SetT(p->rgb[1],light);  SetT(p->rgb[2],dark );  //  if ( fon == 0xfffffe )    {    p->rgb[0].rgbtRed = ((WORD)p->rgb[1].rgbtRed+(WORD)p->rgb[2].rgbtRed)/2;    p->rgb[0].rgbtBlue = ((WORD)p->rgb[1].rgbtBlue+(WORD)p->rgb[2].rgbtBlue)/2;    p->rgb[0].rgbtGreen = ((WORD)p->rgb[1].rgbtGreen+(WORD)p->rgb[2].rgbtGreen)/2;    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~